// Upload names are immutable timestamp/UUID pairs generated by the API.
export const uploadedImageFilename = /^\d+-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|jpeg|png|webp)$/i;

export function imageSourcePath(src: string): string | null {
  if (!src.startsWith("/uploads/")) return null;
  const filename = src.slice("/uploads/".length);
  return uploadedImageFilename.test(filename) ? `/image-source/${filename}` : null;
}
